def align_text(text):
    words = text.split()
    aligned_text = ""
    for index, word in enumerate(words, start=1):
        aligned_text += word
        if index % 6 == 0:
            aligned_text += "\n"
        else:
            aligned_text += " "
    return aligned_text.strip()

